-- RESTAURAR LOS DATOS DE DEMOSTRACIÓN DEL MARKETPLACE (sitio público + Consola)
--
-- Deja los datos principales que entregó Wellq / Alloxentric, IGUALES en el sitio y en la Consola:
-- 7 cuidadoras (6 aprobadas y 1 pendiente) con las mismas reseñas, notas, puntos y estado de pago en los dos lados,
-- la familia demo con su familiar y su trabajo activo con María, y los artículos de apoyo.
--   Cuentas: familia@demo.cl / Familia123!   maria@cuidado.cl / Cuidado123!   (y las demás cuidadoras de ejemplo)
--
-- Cómo usarlo: Supabase -> SQL Editor -> pegar TODO -> Run.
--
-- ATENCIÓN: primero BORRA todo el marketplace (usuarios, familiares, cuidadoras con sus documentos, reseñas, puntos,
-- chats, solicitudes, trabajos, visitas y artículos, del sitio y de la Consola) y luego carga los datos de demostración.
-- No toca admin_users, auditoría, métricas ni tickets. Va en una sola transacción: si algo falla, no cambia nada.

BEGIN;

DELETE FROM chat_messages;
DELETE FROM chat_conversations;
DELETE FROM hire_requests;
DELETE FROM caregiver_engagements;
DELETE FROM contact_requests;
DELETE FROM caregiver_reviews;
DELETE FROM caregiver_profile_views;
DELETE FROM caregiver_documents;
DELETE FROM caregiver_profiles;
DELETE FROM patient_members;
DELETE FROM patients;
DELETE FROM refresh_sessions;
DELETE FROM users;
DELETE FROM market_product_clicks;
DELETE FROM market_products;
DELETE FROM marketplace_caregiver_documents;
DELETE FROM marketplace_caregiver_points_log;
DELETE FROM marketplace_caregiver_reviews;
DELETE FROM marketplace_caregivers;
DELETE FROM marketplace_products;


-- Resumen: deberías ver 7 usuarios de cuidadoras + 1 familia, 7 cuidadoras en cada lado, 58 reseñas en cada lado y 6 artículos.
SELECT 'SITIO · usuarios' AS tabla, count(*) AS filas FROM users
UNION ALL SELECT 'SITIO · cuidadoras', count(*) FROM caregiver_profiles
UNION ALL SELECT 'SITIO · reseñas', count(*) FROM caregiver_reviews
UNION ALL SELECT 'SITIO · artículos', count(*) FROM market_products
UNION ALL SELECT 'CONSOLA · cuidadoras', count(*) FROM marketplace_caregivers
UNION ALL SELECT 'CONSOLA · reseñas', count(*) FROM marketplace_caregiver_reviews
UNION ALL SELECT 'CONSOLA · puntos', count(*) FROM marketplace_caregiver_points_log
UNION ALL SELECT 'CONSOLA · artículos', count(*) FROM marketplace_products;

COMMIT;
